export type ArrowDirection = "up" | "down" | "left" | "right";

export const ArrowIcon: React.FC<{
  direction?: ArrowDirection;
  size?: number;
  color?: string;
}> = ({ direction = "right", size = 24, color = colors.grayscale[100] }) => {
  if (direction === "up") return <ChevronUp size={size} color={color} />;
  if (direction === "down") return <ChevronDown size={size} color={color} />;
  if (direction === "left") return <ChevronLeft size={size} color={color} />;
  return <ChevronRight size={size} color={color} />;
};

export const EyeIcon: React.FC<{
  visible?: boolean;
  size?: number;
  color?: string;
}> = ({ visible = true, size = 20, color = colors.grayscale[100] }) => {
  return visible ? (
    <Eye size={size} color={color} />
  ) : (
    <EyeOff size={size} color={color} />
  );
};

export type ActionIconName =
  | "notification"
  | "close"
  | "camera"
  | "more"
  | "favorite"
  | "heart-fill"
  | "archive"
  | "goal"
  | "premium"
  | "tick-circle"
  | "scan"
  | "gallery"
  | "search"
  | "filter"
  | "plus"
  | "check";

export const ActionIcon: React.FC<{
  name: ActionIconName;
  size?: number;
  color?: string;
}> = ({ name, size = 24, color = colors.grayscale[100] }) => {
  switch (name) {
    case "notification":
      return <Bell size={size} color={color} />;
    case "close":
      return <X size={size} color={color} />;
    case "camera":
      return <Camera size={size} color={color} />;
    case "more":
      return <MoreVertical size={size} color={color} />;
    case "favorite":
      return <Heart size={size} color={color} />;
    case "heart-fill":
      return <Heart size={size} color={colors.primary[100]} fill={colors.primary[100]} />;
    case "archive":
      return <BookmarkCheck size={size} color={color} />;
    case "goal":
      return <Award size={size} color={color} />;
    case "premium":
      return <Crown size={size} color={color} />;
    case "tick-circle":
      return <CheckCircle2 size={size} color={colors.primary[100]} />;
    case "scan":
      return <ScanLine size={size} color={color} />;
    case "gallery":
      return <ImageIcon size={size} color={color} />;
    case "search":
      return <Search size={size} color={color} />;
    case "filter":
      return <SlidersHorizontal size={size} color={color} />;
    case "plus":
      return <Plus size={size} color={color} />;
    case "check":
      return <Check size={size} color={color} strokeWidth={3} />;
  }
};

